css:
/* Truck Country brand layer — the few places the design system cannot reach
   from site/tokens.json alone, because blocks.css hard-codes the value. */

/* The shell's side padding comes from the design system, not from --space-4,
   which blocks.css hard-codes for a section's own container. */
.bz-section > .bz-container{padding-inline:var(--container-pad)}
@media (max-width:1100px){.bz-section > .bz-container{padding-inline:var(--container-pad-tablet)}}
@media (max-width:640px){.bz-section > .bz-container{padding-inline:var(--container-pad-mobile)}}

/* Headings are Oswald 700, tight, and uppercase. blocks.css sets 800. */
.bz-block h1,.bz-block h2{font-weight:700}
.bz-block h1{line-height:.98;letter-spacing:-.01em}
.bz-block h2{line-height:1.1;letter-spacing:-.01em}
.bz-block h3{font-weight:600}

/* Buttons: square, Oswald, uppercase, white on red. */
.bz-btn{font-weight:600;font-size:14px;line-height:normal;letter-spacing:.05em;text-transform:uppercase;padding:16px 32px;border-radius:0}
.bz-btn--primary,.bz-btn--primary:hover{color:#fff}
.bz-btn--primary{border:0}
.bz-btn--secondary{border-color:var(--line)}
.bz-btn--on-dark.bz-btn--secondary{border-width:1.5px;border-color:rgba(255,255,255,.6)}
.bz-btn--on-dark.bz-btn--secondary:hover{background:rgba(255,255,255,.12);border-color:#fff;color:#fff}

/* Eyebrows are red, wide-tracked Oswald. */
.bz-eyebrow{font-family:var(--font-heading);font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.bz-section--bg-ink .bz-eyebrow{color:var(--accent)}

/* Nav is Oswald, uppercase, white on the grey header; red on hover. */
.bz-navitem>a,.bz-navlabel{font-family:var(--font-heading);font-weight:600;letter-spacing:.06em;text-transform:uppercase}

/* Sharp corners throughout — a deliberate brand choice, not an oversight. */
.bz-figure img,.bz-card,.bz-input{border-radius:0}

/* The type ramp the desktop sizes are drawn to does not fit a phone. */
@media (max-width:1100px){
  .bz-block h1{font-size:60px}
  .bz-block h2{font-size:34px}
}
@media (max-width:640px){
  .bz-block h1{font-size:44px}
  .bz-block h2{font-size:28px}
}

/* Skip link — off-screen until focused. */
.tc-skip{position:absolute;left:-999px;top:0;z-index:100;background:#fff;color:#14151A;padding:12px 16px;font:600 14px var(--font-body);text-decoration:none}
.tc-skip:focus{left:8px;top:8px}
/* ---------------- inner-page component system (handoff §"Inner-page") ----- */

/* Form card: 2-up fields, labels Inter 600 15px, square 48px inputs, red focus
   ring. The renderer puts the fields straight inside <form>, so the grid lives
   there and everything that is not a half-width field spans the row. */
.bz-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:20px;background:none;border:0;border-radius:0;padding:0;max-width:none}
.bz-form > *{grid-column:1/-1}
.bz-form > .bz-field--half{grid-column:auto}
.bz-form__t{font-family:var(--font-heading);font-weight:600;font-size:20px;letter-spacing:.04em;text-transform:uppercase;margin:0}
.bz-field{display:flex;flex-direction:column;gap:6px}
.bz-label{font-family:var(--font-body);font-weight:600;font-size:15px;color:#14151A}
.bz-req{color:#C41230}
.bz-input{font:400 16px var(--font-body);padding:12px 14px;min-height:48px;box-sizing:border-box;width:100%;border:1px solid #54565C;border-radius:0;background:#fff;color:#14151A}
.bz-input:focus-visible{outline:3px solid #C41230;outline-offset:1px}
textarea.bz-input{min-height:120px}
.bz-help{font-size:13px;color:#54565C;margin:0}
.bz-form__status{font-size:14px;font-weight:600;color:#A00F27;margin:0}
.bz-field--consent .bz-choice{display:grid;grid-template-columns:24px 1fr;gap:12px;align-items:start;font-size:15px;line-height:1.5;cursor:pointer}
.bz-field--consent input[type="checkbox"]{width:24px;height:24px;accent-color:#C41230;margin:0}
.bz-field--hp{position:absolute;left:-9999px}
.bz-form > button[type="submit"]{width:100%;min-height:56px;background:#C41230;color:#fff;border:0;border-radius:0;font-family:var(--font-heading);font-weight:600;font-size:16px;letter-spacing:.1em;text-transform:uppercase;padding:16px 24px}
.bz-form > button[type="submit"]:hover{background:#8f0d21;color:#fff}

/* FAQ: a divider per row, Oswald questions, and a red "+" that turns on open. */
.bz-faqs{border-top:1px solid #EDEBE3}
.bz-faq{border-bottom:1px solid #EDEBE3}
.bz-faq > summary{display:flex;align-items:center;justify-content:space-between;gap:16px;cursor:pointer;list-style:none;padding:20px 0;font-family:var(--font-heading);font-weight:600;font-size:18px;letter-spacing:.02em;color:#14151A}
.bz-faq > summary::-webkit-details-marker{display:none}
.bz-faq > summary::after{content:"+";color:#C41230;font:700 28px/1 var(--font-heading);transition:transform .2s ease}
.bz-faq[open] > summary::after{transform:rotate(45deg)}
.bz-faq__a{padding:0 0 20px;color:#54565C;font-size:16px;line-height:1.6;max-width:80ch}
@media (prefers-reduced-motion:reduce){.bz-faq > summary::after{transition:none}}

/* The "helpful to have on hand" list is a feature list at one column. */
.bz-block--list .bz-grid--1{grid-template-columns:1fr;gap:4px}
.bz-block--list .bz-grid--1 li{list-style:disc;margin-left:20px;color:#54565C}
.bz-block--list .bz-grid--1 li .bz-feat__l{font-weight:400;font-size:16px}

/* Site-map strip and footer row: inline link rows. */
[data-bz-node="sm-strip-links"] p{display:flex;flex-wrap:wrap;gap:20px;align-items:center;margin:0;font-size:14px;color:#fff}
[data-bz-node="sm-strip-links"] a{color:#fff;text-decoration:none}
[data-bz-node="sm-strip-links"] a:hover{color:#ff8da0}
[data-bz-node="sm-strip-links"] small{font-family:var(--font-heading);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#8F8F8F}
[data-bz-node="sm-foot-links"] p{display:flex;flex-wrap:wrap;gap:20px;align-items:center;margin:0;font-size:14px}
[data-bz-node="sm-foot-links"] small{font-family:var(--font-heading);font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#54565C}
[data-bz-node="sm-title"] h1{font-family:var(--font-heading);font-weight:700;font-size:clamp(32px,5vw,56px);line-height:1;text-transform:none;margin:0}
[data-bz-node="sm-count"] p{font-size:14px;color:#54565C;margin:0;text-align:right}
@media (max-width:640px){[data-bz-node="sm-count"] p{text-align:left}}

/* The form card carries no title of its own in this design. */
.bz-form__t{display:none}

/* A feature list standing in for a plain bulleted list. */
.bz-block--list .bz-grid--1{grid-template-columns:1fr;gap:4px;list-style:disc;padding-left:20px}
.bz-block--list .bz-grid--1 .bz-feature__t{font:400 16px/1.6 var(--font-body);color:#54565C;text-transform:none;margin:0}
.bz-block--list .bz-grid--1 .bz-feature{display:list-item;color:#54565C}

/* FAQ rows sit on the page, not on a card. */
.bz-faqs{background:none}

/* The breadcrumb sits directly under the header, with no block padding. */
.bz-block--breadcrumb{padding-block:0}
